/// <summary>
///     extension of class <c>AVAPCMEmailProcessor</c>
/// </summary>
[ExtensionOf(classStr(AVAPCMEmailProcessor))]
final class AVAAVAPCMEmailProcessorCls_Extension
{
    public AVAPCMEmailSetupId   clsAVAPCMEmailSetupIdReplacement;
    public AVAPCMEmailSetup     clsAVAPCMEmailSetupReplacement;
    public AVAPCMEmailFormatter clsAVAPCMEmailFormatter;

    public SRSPrintDestinationSettings  clsSRSPrintDestinationSettings;
    public SrsReportEMailDataContract	clsEmailContract;

}

Method.Source:
/// <summary>
///     AVA <c>createSalesLineTmpTableRecord</c> method.
///     Intialize data for sending the email
///     AVA - Schneider 16.04.2024
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
///     True, if email setup was found
/// </returns>
public boolean initialize()
{
    boolean retVal;

    clsSRSPrintDestinationSettings  = dataContract.parmPrintSettings();
    clsEmailContract                = clsSRSPrintDestinationSettings.parmEMailContract();

    if(dataContract.parmRdpContract() is AVASalesOrderDelegationReportContract)
    {
        clsAVAPCMEmailSetupReplacement      = clsSRSPrintDestinationSettings.parmAVAPCMEmailSetupReplacement();
        clsAVAPCMEmailSetupIdReplacement    = clsSRSPrintDestinationSettings.parmAVAPCMEmailSetupIdReplacement();
        clsAVAPCMEmailFormatter             = clsSRSPrintDestinationSettings.parmAVAPCMEmailFormatter();

        if(!clsAVAPCMEmailFormatter)
        {
            clsAVAPCMEmailFormatter = AVAPCMEmailFormatter::construct(dataContract);
        }
        clsAVAPCMEmailFormatter.avaSetTables2Check();
    }

    if(     !clsAVAPCMEmailSetupReplacement.RecId 
        &&  clsAVAPCMEmailSetupIdReplacement        )
    {
        clsAVAPCMEmailSetupReplacement = AVAPCMEmailSetup::find(clsAVAPCMEmailSetupIdReplacement);
    }

    retVal = next initialize();

    if(dataContract.parmRdpContract() is AVASalesOrderDelegationReportContract)
    {
        emailFormatter  = clsAVAPCMEmailFormatter;

        if(clsAVAPCMEmailSetupReplacement.RecId)
        {
            emailSetup  = clsAVAPCMEmailSetupReplacement;
        }
        else
        {
            emailSetup  = AVAPCMEmailSetup::find(AVASalesParameters::find().EmailSetupId);
        }

        if(     emailSetup.RecId
            &&  retVal == false )
        {
            retVal              = true;
            //Set initial file name
            attachmentFileName  = emailSetup.Filename;
            attachDocuments	    = emailSetup.IncludeExternalDocument;
        }
    }
    return retVal;
}

