/// <summary>
///    AVA <c>parmclsAVAPCMEmailSetupIdReplacement</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>AVAPCMEmailSetupId</c> as type
/// </param>
/// <returns>
///    <c>AVAPCMEmailSetupId</c> as return value
/// </returns>
public AVAPCMEmailSetupId parmclsAVAPCMEmailSetupIdReplacement(AVAPCMEmailSetupId _parmValue = clsAVAPCMEmailSetupIdReplacement)
{
    clsAVAPCMEmailSetupIdReplacement = _parmValue;

    return clsAVAPCMEmailSetupIdReplacement;
}

/// <summary>
///    AVA <c>parmclsAVAPCMEmailSetupReplacement</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>AVAPCMEmailSetup</c> as type
/// </param>
/// <returns>
///    <c>AVAPCMEmailSetup</c> as return value
/// </returns>
public AVAPCMEmailSetup parmclsAVAPCMEmailSetupReplacement(AVAPCMEmailSetup _parmValue = clsAVAPCMEmailSetupReplacement)
{
    clsAVAPCMEmailSetupReplacement = _parmValue;

    return clsAVAPCMEmailSetupReplacement;
}
